const CACHE='lyrics-player-v39-centered-metadata';
const SHELL=['./','index.html','app.js?v=35','apple-ui.css?v=39','appearance.js?v=38','share-card.js?v=34','share-video.js?v=34','lyric-share.js?v=34','catalog-lizhi.js?v=36','manifest.webmanifest','icon.svg','cover.jpg','cover-lizhi.jpg',...Array.from({length:31},(_,i)=>`lyrics/${String(i+1).padStart(2,'0')}.lrc`)];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(SHELL.map(url=>new Request(url,{cache:'reload'})))).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith('lyrics-player-')&&key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET')return;const url=new URL(event.request.url);if(event.request.destination==='audio'||url.pathname.includes('/audio/')||event.request.headers.has('range'))return;event.respondWith(caches.match(event.request).then(hit=>hit||fetch(event.request).then(response=>{if(response.ok&&url.origin===self.location.origin){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy))}return response}).catch(()=>event.request.mode==='navigate'?caches.match('index.html'):Response.error())))});
